<script setup>
import {ref,onMounted,watch} from 'vue'
import {api,post} from '../api'
import KnowledgeDetail from '../components/KnowledgeDetail.vue'
const props=defineProps({mode:{type:String,default:'box'}})
const emit=defineEmits(['navigate','ask'])
const members=ref([]),medicines=ref([]),owner=ref(''),error=ref(''),busy=ref(false),message=ref(''),samples=ref([]),sample=ref(''),text=ref(''),ingredients=ref(''),matches=ref([]),report=ref(null),riskAccepted=ref(false),selected=ref(null),summary=ref(null)
const empty=()=>({name:'',spec:'',owner:'',dose:'',frequency:'',method:'',location:'',stock:'',expiry_date:'',original_text:''})
const form=ref(empty()),confirmed=ref(false)
watch(()=>[form.value.name,form.value.owner,ingredients.value],()=>{report.value=null;riskAccepted.value=false;confirmed.value=false})
async function load(){try{medicines.value=await api('/medicines'+(owner.value?'?owner='+encodeURIComponent(owner.value):''));const member=members.value.find(m=>m.name===owner.value);summary.value=member?await api(`/members/${member.id}/risk-report`):null}catch(e){error.value=e.message}}
async function parse(){busy.value=true;error.value='';try{const card=await post('/instruction/parse',sample.value?{sample_id:sample.value}:{ocr_text:text.value});form.value={...empty(),...card,owner:owner.value,expiry_date:''};ingredients.value='';matches.value=[];confirmed.value=false;message.value='已解析，请核对药名、有效成分、使用者及用法。演示样例不是审核知识。'}catch(e){error.value=e.message}finally{busy.value=false}}
async function match(){try{matches.value=await api('/knowledge/drugs?keyword='+encodeURIComponent(form.value.name));message.value=matches.value.length?'请选择并核对匹配结果；不会自动替换。':'暂未收录，请依据原说明书手动核对成分。'}catch(e){error.value=e.message}}
function choose(entry){form.value.name=entry.name;ingredients.value=entry.ingredients.join('、');message.value='已填入匹配结果，请人工核对确认。';matches.value=[]}
async function check(){const member=members.value.find(m=>m.name===form.value.owner);if(!member){error.value='请选择使用者';return}error.value='';try{report.value=await post('/interactions/check',{member_id:member.id,candidate_name:form.value.name,candidate_ingredients:ingredients.value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean)});riskAccepted.value=false}catch(e){error.value=e.message}}
async function save(){if(!report.value){await check();message.value='请查看检查结果，再次确认加入。';return}if(report.value.count&&!riskAccepted.value){error.value='请阅读风险并确认是否继续加入';return}busy.value=true;error.value='';try{await post('/medicines',{...form.value,confirmed:true,ingredients:ingredients.value.split(/[、,，]/).map(s=>s.trim()).filter(Boolean),risk_accepted:riskAccepted.value});form.value=empty();ingredients.value='';confirmed.value=false;report.value=null;message.value='药品与核对状态已保存';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(m){if(!confirm(`删除“${m.name}”？关联提醒将停用，历史保留。`))return;try{await api(`/medicines/${m.id}`,{method:'DELETE'});selected.value=null;await load()}catch(e){error.value=e.message}}
onMounted(async()=>{try{[members.value,samples.value]=await Promise.all([api('/members'),api('/instruction/samples')]);await load()}catch(e){error.value=e.message}})
</script>
<template><p class="error" role="alert" v-if="error">{{error}}</p><p class="feedback" role="status" v-if="message">{{message}}</p><template v-if="props.mode==='box'"><section class="hero boxhero"><h2>药箱状态</h2><p>{{owner||'全部成员'}} · {{medicines.length}} 件药品</p><div class="metrics"><div class="metric"><b>{{medicines.length}}</b><span>当前药品</span></div><div class="metric"><b>{{summary?.count??'—'}}</b><span>已收录风险</span></div><div class="metric"><b>{{medicines.filter(m=>!m.confirmed).length}}</b><span>待核对</span></div></div></section><div class="toolbar"><select v-model="owner" @change="load"><option value="">全部成员</option><option v-for="m in members" :key="m.id" :value="m.name">{{m.name}}</option></select><button @click="emit('navigate','风险报告')">风险详情</button></div><p class="feedback" v-if="summary">{{summary.highest_level}} · {{summary.message}}</p><article v-for="m in medicines" :key="m.id"><div class="boxhead"><div class="boxleft"><div class="boxicon">💊</div><div><h2>{{m.name}}</h2><p>{{m.owner}} · {{m.spec}}</p></div></div><span class="tag" :class="m.confirmed?'green':'orange'">{{m.confirmed?'已核对':'待核对'}}</span></div><div class="meta"><div><small>位置</small><b>{{m.location||'未填写'}}</b></div><div><small>有效期</small><b>{{m.expiry_date||'未填写'}}</b></div><div><small>库存</small><b>{{m.stock||'未填写'}}</b></div></div><div class="toolbar"><button @click="selected=m">药品详情</button><button @click="emit('ask',m.name)">问问 AI</button><button class="quiet" @click="remove(m)">删除</button></div></article><p class="empty" v-if="!medicines.length">药箱暂无药品，核对后添加。</p><section class="panel" v-if="selected"><h2>{{selected.name}}</h2><p>使用者：{{selected.owner}}</p><p>用法：{{selected.dose}} · {{selected.frequency}} · {{selected.method}}</p><p>注意事项：{{selected.risks.join('；')||'请核对原说明书'}}</p><details><summary>保存的原始文字</summary><p>{{selected.original_text||'未保存原文'}}</p></details><button @click="emit('ask',selected.name)">就此药询问 AI</button></section><button class="primary" @click="emit('navigate','扫一扫')">＋ 添加药品</button></template><template v-else><section class="panel"><h2>说明书文字解析</h2><p class="subtitle">粘贴原文或选择演示样例。图片 OCR 尚未接入。</p><select v-model="sample"><option value="">使用下方原文解析</option><option v-for="s in samples" :key="s.id" :value="s.id">演示样例 · {{s.name}}</option></select><textarea v-model="text" :disabled="!!sample" rows="4" placeholder="粘贴说明书文字"></textarea><button :disabled="busy||(!sample&&!text.trim())" @click="parse">解析并填写核对表</button></section><section class="panel"><h2>人工核对药品</h2><form @submit.prevent="save"><div class="form-grid"><label>药品名称 *<input v-model="form.name" required></label><label>使用者 *<select v-model="form.owner" required><option value="" disabled>请选择成员</option><option v-for="m in members" :key="m.id" :value="m.name">{{m.name}}</option></select></label></div><button type="button" @click="match" :disabled="!form.name.trim()">匹配标准名与成分</button><div v-for="entry in matches" :key="entry.id"><button type="button" @click="choose(entry)">{{entry.name}} · {{entry.ingredients.join('、')}} → 选择并核对</button></div><label>有效成分 *（顿号分隔）<input v-model="ingredients" required placeholder="依据原说明书核对填写"></label><div class="form-grid"><label>规格<input v-model="form.spec"></label><label>一次用量 *<input v-model="form.dose" required></label><label>频次 *<input v-model="form.frequency" required></label><label>服用方式<input v-model="form.method"></label><label>库存<input v-model="form.stock"></label><label>存放位置<input v-model="form.location"></label><label>有效期<input type="date" v-model="form.expiry_date"></label></div><label class="check"><input type="checkbox" v-model="confirmed">我已核对药名、有效成分、使用者和用法用量</label><button type="button" :disabled="!confirmed||busy" @click="check">入箱前检查用药风险</button><div v-if="report"><p class="feedback">{{report.message}}</p><p class="error" v-if="report.missing.length">资料不足：{{report.missing.join('、')}}，未命中不代表安全。</p><details v-for="risk in report.items" :key="risk.id"><summary>{{risk.level}} · {{risk.drugs.join(' ＋ ')}}</summary><KnowledgeDetail :entry="risk"/></details><label class="check" v-if="report.count"><input type="checkbox" v-model="riskAccepted">我已阅读风险和依据，知晓需咨询医生或药师，仍选择加入</label><button type="button" v-if="report.count" @click="emit('navigate','药箱')">暂不加入，返回药箱</button></div><button class="primary" :disabled="busy||!confirmed||!ingredients.trim()">{{busy?'处理中…':report?'确认加入药箱':'检查风险后加入'}}</button></form></section></template></template>
